# Let me try a faster approach - use numpy for speed and a smarter algorithm
import random
import itertools
import time

def solve_social_golfers_fast(n_weeks=6, n_groups=10, n_players=5, seed=42):
    random.seed(seed)
    n_golfers = n_groups * n_players

    # Represent schedule as assignment[w][p] = group of player p in week w
    # Initialize with random valid partitions
    assignment = []
    for w in range(n_weeks):
        golfers = list(range(n_golfers))
        random.shuffle(golfers)
        week_assign = [0] * n_golfers
        for g in range(n_groups):
            for i in range(n_players):
                week_assign[golfers[g*n_players + i]] = g
        assignment.append(week_assign)

    def compute_conflicts(assignment):
        pair_weeks = {}
        conflicts = 0
        for w in range(n_weeks):
            # Group players by their group
            groups = [[] for _ in range(n_groups)]
            for p in range(n_golfers):
                groups[assignment[w][p]].append(p)
            for g in range(n_groups):
                grp = groups[g]
                for i in range(len(grp)):
                    for j in range(i+1, len(grp)):
                        key = (grp[i], grp[j]) if grp[i] < grp[j] else (grp[j], grp[i])
                        if key in pair_weeks:
                            conflicts += 1
                        else:
                            pair_weeks[key] = w
        return conflicts

    def compute_conflict_delta(assignment, w, p1, p2):
        """Compute change in conflicts if we swap p1 and p2 in week w"""
        # p1 is in group g1, p2 is in group g2
        g1 = assignment[w][p1]
        g2 = assignment[w][p2]
        if g1 == g2:
            return 0

        # Get current groups
        groups = [[] for _ in range(n_groups)]
        for p in range(n_golfers):
            groups[assignment[w][p]].append(p)

        # Count pairs involving p1 in g1 (will be removed)
        # Count pairs involving p2 in g2 (will be removed)
        # Count pairs involving p1 in g2 (will be added)
        # Count pairs involving p2 in g1 (will be added)

        # Build pair count for all weeks except w
        pair_count = {}
        for ww in range(n_weeks):
            if ww == w:
                continue
            grps = [[] for _ in range(n_groups)]
            for p in range(n_golfers):
                grps[assignment[ww][p]].append(p)
            for g in range(n_groups):
                grp = grps[g]
                for i in range(len(grp)):
                    for j in range(i+1, len(grp)):
                        key = (min(grp[i],grp[j]), max(grp[i],grp[j]))
                        pair_count[key] = pair_count.get(key, 0) + 1

        delta = 0
        # Pairs being removed (p1 with g1 members, p2 with g2 members)
        for p in groups[g1]:
            if p != p1:
                key = (min(p,p1), max(p,p1))
                if pair_count.get(key, 0) >= 1:
                    delta -= 1  # removing a conflict
        for p in groups[g2]:
            if p != p2:
                key = (min(p,p2), max(p,p2))
                if pair_count.get(key, 0) >= 1:
                    delta -= 1

        # Pairs being added (p1 with g2 members, p2 with g1 members)
        for p in groups[g2]:
            if p != p2:
                key = (min(p,p1), max(p,p1))
                if pair_count.get(key, 0) >= 1:
                    delta += 1
        for p in groups[g1]:
            if p != p1:
                key = (min(p,p2), max(p,p2))
                if pair_count.get(key, 0) >= 1:
                    delta += 1

        return delta

    conflicts = compute_conflicts(assignment)
    print(f"Initial conflicts: {conflicts}")
    return conflicts

