import random
import time

def solve_with_restarts(n_weeks=6, n_groups=10, n_players=5, time_limit=10):
    n_golfers = n_groups * n_players

    def random_schedule(seed):
        random.seed(seed)
        sched = []
        for w in range(n_weeks):
            golfers = list(range(n_golfers))
            random.shuffle(golfers)
            week = [list(golfers[g*n_players:(g+1)*n_players]) for g in range(n_groups)]
            sched.append(week)
        return sched

    def count_conflicts_and_pairs(sched):
        pair_count = {}
        for w in range(n_weeks):
            for g in range(n_groups):
                grp = sched[w][g]
                for i in range(n_players):
                    for j in range(i+1, n_players):
                        a, b = min(grp[i], grp[j]), max(grp[i], grp[j])
                        key = (a, b)
                        pair_count[key] = pair_count.get(key, 0) + 1
        conflicts = sum(max(0, v-1) for v in pair_count.values())
        return conflicts, pair_count

    def delta_swap(sched, w, g1, g2, p1_idx, p2_idx, pair_count):
        """Compute delta conflicts for swapping player at g1[p1_idx] with g2[p2_idx] in week w"""
        p1 = sched[w][g1][p1_idx]
        p2 = sched[w][g2][p2_idx]

        # Count pairs in other weeks
        other_pair_count = {}
        for ww in range(n_weeks):
            if ww == w:
                continue
            for g in range(n_groups):
                grp = sched[ww][g]
                for i in range(n_players):
                    for j in range(i+1, n_players):
                        a, b = min(grp[i], grp[j]), max(grp[i], grp[j])
                        key = (a, b)
                        other_pair_count[key] = other_pair_count.get(key, 0) + 1

        delta = 0
        # Pairs being removed: p1 with g1 members, p2 with g2 members
        for p in sched[w][g1]:
            if p != p1:
                key = (min(p,p1), max(p,p1))
                if other_pair_count.get(key, 0) >= 1:
                    delta -= 1  # was a conflict, now removed
        for p in sched[w][g2]:
            if p != p2:
                key = (min(p,p2), max(p,p2))
                if other_pair_count.get(key, 0) >= 1:
                    delta -= 1

        # Pairs being added: p1 with g2 members, p2 with g1 members
        for p in sched[w][g2]:
            if p != p2:
                key = (min(p,p1), max(p,p1))
                if other_pair_count.get(key, 0) >= 1:
                    delta += 1
        for p in sched[w][g1]:
            if p != p1:
                key = (min(p,p2), max(p,p2))
                if other_pair_count.get(key, 0) >= 1:
                    delta += 1

        return delta

    start_time = time.time()
    best_overall = None
    best_conflicts_overall = float('inf')

    for restart in range(100):
        if time.time() - start_time > time_limit:
            break

        sched = random_schedule(restart * 1000 + 42)
        conflicts, pair_count = count_conflicts_and_pairs(sched)

        # Local search
        no_improve = 0
        for iteration in range(100000):
            if time.time() - start_time > time_limit:
                break
            if conflicts == 0:
                break

            w = random.randint(0, n_weeks-1)
            g1, g2 = random.sample(range(n_groups), 2)
            p1_idx = random.randint(0, n_players-1)
            p2_idx = random.randint(0, n_players-1)

            # Do swap
            p1 = sched[w][g1][p1_idx]
            p2 = sched[w][g2][p2_idx]
            sched[w][g1][p1_idx] = p2
            sched[w][g2][p2_idx] = p1

            new_conflicts, new_pair_count = count_conflicts_and_pairs(sched)

            if new_conflicts <= conflicts:
                conflicts = new_conflicts
                pair_count = new_pair_count
                no_improve = 0
            else:
                # Undo
                sched[w][g1][p1_idx] = p1
                sched[w][g2][p2_idx] = p2
                no_improve += 1

                if no_improve > 1000:
                    break

        if conflicts < best_conflicts_overall:
            best_conflicts_overall = conflicts
            best_overall = [[[p for p in g] for g in week] for week in sched]
            print(f"Restart {restart}: best={best_conflicts_overall}")

        if best_conflicts_overall == 0:
            break

    return best_overall, best_conflicts_overall

result, conflicts = solve_with_restarts(time_limit=12)
